def recent_posts(conn, page, per_page=20):
    page = max(int(page), 1)
    per_page = min(int(per_page), 100)
    offset = (page - 1) * per_page
    rows = conn.execute(f"SELECT id, title FROM posts ORDER BY id DESC LIMIT {per_page} OFFSET {offset}").fetchall()
    return {"page": page, "posts": [{"id": r[0], "title": r[1]} for r in rows]}

def export_region_rows(conn, table, region_codes, columns, limit=1000):
    permitted = {
        "stations": ("code", "name", "region", "elevation"),
        "readings": ("station_code", "taken_at", "temperature", "region"),
    }
    if table not in permitted:
        raise ValueError("unknown table")
    for column in columns:
        if column not in permitted[table]:
            raise ValueError("unknown column " + column)
    if not region_codes:
        return []
    literals = sql.SQL(", ").join(sql.Literal(code) for code in region_codes)
    query = sql.SQL("SELECT {cols} FROM {tbl} WHERE region IN ({codes}) ORDER BY 1 LIMIT {n}").format(
        cols=sql.SQL(", ").join(sql.Identifier(c) for c in columns),
        tbl=sql.Identifier(table),
        codes=literals,
        n=sql.Literal(int(limit)),
    )
    with conn.cursor() as cur:
        cur.execute(query)
        rows = cur.fetchall()
    result = [dict(zip(columns, row)) for row in rows]
    log.info("exported %s rows from %s", len(result), table)
    return result

def export_table(conn, name, columns):
    tables = {"customers": ("id", "name", "email"), "products": ("sku", "name", "price")}
    if name not in tables:
        raise ValueError(name)
    allowed = tables[name]
    cols = [c for c in columns if c in allowed] or list(allowed)
    cur = conn.cursor()
    cur.execute(f"SELECT {', '.join(cols)} FROM {name} ORDER BY {cols[0]}")
    rows = cur.fetchall()
    return {"columns": cols, "rows": rows}

