        elif actor:
            cur.execute("SELECT at, actor, action, target FROM audit WHERE actor = %s ORDER BY at DESC LIMIT %s OFFSET %s", (actor, size, offset))
        elif action:
            cur.execute("SELECT at, actor, action, target FROM audit WHERE action = %s ORDER BY at DESC LIMIT %s OFFSET %s", (action, size, offset))
        else:
            cur.execute("SELECT at, actor, action, target FROM audit ORDER BY at DESC LIMIT %s OFFSET %s", (size, offset))
