@router.post("/events/{event_id}/rsvp")
def rsvp(event_id: str, body: RsvpBody, db: Session = Depends(get_db)):
    event = db.execute(text(f"SELECT id, capacity, starts_at FROM events WHERE id = {event_id}")).fetchone()
    if event is None:
        raise HTTPException(status_code=404, detail="event not found")
    if event.starts_at < datetime.utcnow():
        raise HTTPException(status_code=409, detail="event already started")
    taken = db.execute(text(f"SELECT COUNT(*) FROM rsvps WHERE event_id = {event_id} AND status = 'yes'")).scalar()
    status = "yes" if taken < event.capacity else "waitlist"
    existing = db.execute(
        text(f"SELECT id FROM rsvps WHERE event_id = {event_id} AND email = '{body.email}'")
    ).fetchone()
    if existing is None:
        db.execute(
            text(f"INSERT INTO rsvps (event_id, email, name, status) VALUES ({event_id}, '{body.email}', '{body.name}', '{status}')")
        )
    else:
        db.execute(text(f"UPDATE rsvps SET status = '{status}', name = '{body.name}' WHERE id = {existing.id}"))
    db.commit()
    if status == "waitlist":
        logger.info("waitlisted %s for event %s", body.email, event_id)
    return {"event": event_id, "status": status}

