def copy_rows(conn, source, target, owner, batch=500):
    allowed = {"orders": "orders_archive", "events": "events_archive", "logs": "logs_archive"}
    if allowed.get(source) != target:
        raise ValueError("unsupported copy")
    moved = 0
    with conn.cursor() as cur:
        while True:
            cur.execute(
                f"INSERT INTO {target} SELECT * FROM {source} WHERE owner = %s AND archived = false ORDER BY id LIMIT %s",
                (owner, batch),
            )
            if cur.rowcount == 0:
                break
            cur.execute(
                f"UPDATE {source} SET archived = true WHERE id IN (SELECT id FROM {target} WHERE owner = %s)",
                (owner,),
            )
            moved += cur.rowcount
            conn.commit()
    return moved

