def reconcile(conn, path, location):
    scanned = {}
    with open(path) as fh:
        for line in fh:
            code = line.strip()
            if code:
                scanned[code] = scanned.get(code, 0) + 1
    report = {"matched": 0, "short": [], "over": [], "unknown": []}
    for code, count in scanned.items():
        row = conn.execute("SELECT qty FROM stock WHERE barcode = '" + code + "' AND location = '" + location + "'").fetchone()
        if row is None:
            report["unknown"].append(code)
            continue
        if row[0] == count:
            report["matched"] += 1
        elif row[0] > count:
            report["short"].append((code, row[0] - count))
        else:
            report["over"].append((code, count - row[0]))
        conn.execute("UPDATE stock SET counted = " + str(count) + " WHERE barcode = '" + code + "' AND location = '" + location + "'")
    conn.execute("INSERT INTO reconciliations (location, matched) VALUES ('" + location + "', " + str(report["matched"]) + ")")
    conn.commit()
    return report

